INSERT INTO books (book_name, cover_image_url, authors, publisher, category, isbn, language, num_pages, edition, price, discount_price, discount_percentage, rating, num_reviews, availability, description) VALUES
('ওঙ্কার', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/8b36f6916_175174.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'চিরায়ত উপন্যাস', '9789848966334', 'বাংলা', 80, '2nd Published, 2023', 200.0, 172, '65% Off', NULL, 5, 'In Stock', '"ওঙ্কার" বইয়ের ভেতর থেকে: আহমদ ছফা সাহিত্যচর্চা শুরু করেন উপন্যাস দিয়ে। বেশ কয়েকটা ছােটো গল্প লিখে হাত মসকের করার প্রচলিত নিয়মটি তিনি মানেননি; তাঁর প্রকাশিত প্রথম বইটিও একটি উপন্যাস। ছফার উপন্যাস আকারে ছােটো হলেও কোনােটাই কিন্তু ছােটো গল্পের সম্প্রসারণ নয়, এগুলাে একেবারেই উপন্যাস। চেনাজানা জীবনের ভেতরের ব্যাপারটা নানা দিক থেকে দেখার দায়িত্ব নিয়ে সমাজ ও রাজনীতির ভাঙাচোরায় কাজ করছে কোন রহস্য, তারই অনুসন্ধানে ছফা নিয়ােজিত। সুখ ও স্বস্তি জলাঞ্জলি দিয়ে তিনি কাজ করেন এমন সব পরিবেশ নিয়ে যা বেশির ভাগ সময়ে তার স্বভাবের অনুকূল নয়। পাঠককে তিনি পরিচয় করিয়ে দিচ্ছেন যাদের সঙ্গে বেশির ভাগ সময়েই তিনি নিজে বা তাঁর পাঠকরা তাদের পছন্দ করেন না; অন্তত তাদের অনেক কাণ্ডকীর্তিতে সায় দেওয়া মুশকিল। সেই খুচরােখাচরা ও টুটাফাটা মানুষের একেকটা আস্ত চেহারা তৈরি করতে ছফাকে রীতিমতাে যুদ্ধ করতে হয় এবং পাঠককে তিনি উস্কে দেন এ যুদ্ধে নেমে পড়তে। ‘ওঙ্কার’-এ আহমদ ছফা গপ্পো ফাঁদতে বসেননি, কাহিনীর সত্র ধরে পাঠককে তিনি টেনে নেন এমন একটি জায়গায় যেখানে পৌছে গল্পটা ভুলে গেলেও কিছু এসে যায় না, কাহিনী গৌণ হয়ে সেখানে প্রবল হয়ে ওঠে অনেক দিনের মানুষ গ্লানি, জড়তা ও শােষণ এবং গ্লানি থেকে মুক্তির রক্তাক্ত সংকল্প।'),
('গাভী বিত্তান্ত', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/123588289_176482.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'চিরায়ত উপন্যাস', '9789848965948', 'বাংলা', 136, '1st Published, 2016', 250.0, 215, '65% Off', NULL, 5, 'In Stock', 'b"গাভী বিত্তান্ত" বইটির সম্পর্কে কিছু কথাঃbr/b গাভী বিত্তান্ত বাংলাদেশের প্রখ্যাত চিন্তাবিদ ও লেখক আহমদ ছফা রচিত একটি বাস্তবিক গভীর পর্যবেক্ষণে রচিত উপন্যাস। উপন্যাসটি ১৯৯৫ খ্রিস্টাব্দে ঢাকা থেকে প্রকাশিত হয়। গাভী বিত্তান্ত উপন্যাসে চিত্রায়িত হয়েছে একজন উপাচার্যের গোলামি আর বিশ্ববিদ্যালয়ে শিক্ষকদের লেজুড়বৃত্তিক রাজনীতির নোংরা কদর্য রূপ।br রসায়নের অধ্যাপক মিয়া মোহাম্মদ আবু জুনায়েদ দেশের সেরা ও প্রাচীনতম বিশ্ববিদ্যালয়ের উপাচার্য নির্বাচিত হয়েছেন। রসায়ন বিভাগের সুন্দরী শিক্ষিকা দিলরুবা খানমের আকর্ষণে জুনায়েদ ডোরাকাটা দলের শিক্ষক রাজনীতিতে সক্রিয় হয়েছিলেন। পূর্ববর্তী উপাচার্যের উপর ক্ষোভবশত দিলরুবা খানম তাঁর নারীপ্রভাবকে কাজে লাগিয়ে জুনায়েদকে উপাচার্য প্যানেলে ঢুকিয়ে দেন। স্বৈরাচারী সরকারের অবাধ্য হবে না বলে রাষ্ট্রপতি (যিনি পদাধিকারবলে সকল বিশ্ববিদ্যালয়ের আচার্যও) জুনায়েককেই উপাচার্য নিয়োগ দেন। এই উপাচার্যের পদে আসীন হওয়ার পর জুনায়েদের চরিত্রের বিবর্তনকে ঘিরে আবর্তিত হয় উপন্যাসের কাহিনী। br ঠিকাদার শেখ তবারক আলী উপাচার্যকে হাতে রাখতে জুনায়েদের মনোবাসনা পূর্ণ করতে একটি দুর্লভজাতের গাভী কিনে দেন এবং ভিসির বাংলোতে শেখ তবারক আলী নিজ জামাতা বুয়েটপাস সিভিল ইঞ্জিনিয়ার আবেদ হোসেনকে দিয়ে গোয়ালঘর বানিয়ে দেন। পরবর্তীতে উপাচার্য আবু জুনায়েদের জীবন এবং বিশ্ববিদ্যালয়ের ভবিষ্যৎ সবটাই হয়ে পড়ে গোয়ালঘরকেন্দ্রিক। এই গোয়ালঘরকে রঙ্গমঞ্চ বানিয়ে আহমদ ছফা বিশ্ববিদ্যালয়গুলোর দৈন্যদশা এবং শিক্ষকরাজনীতির নোংরা বিভিন্ন দিক তুলে ধরেছেন।'),
('বাঙালি মুসলমানের মন', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/ad698e1e1_216454.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'বিবিধ বিষয়ক প্রবন্ধ', '9789848966068', 'বাংলা', 156, '1st Published, 2018', 250.0, 215, '65% Off', NULL, 5, 'In Stock', 'ইতিহাসের বিশ-ত্রিশ বছর কান দীর্ঘ সময় নয়। বাঙালি মুসলমান মুক্তিযুদ্ধের মাধ্যমে যে রাষ্ট্রযন্ত্রটি প্রতিষ্ঠা করেছে সে রাষ্্রর সংকটের অন্ত নেই, কোথাও কোন দিক-নির্দেশনার চিহ্ন পরিদৃশ্যমান নয়। সামাজিক সভ্য এবং ধর্মীয় কুসংস্কার সাম্প্রতিককাল এমন প্রচণ্ড আকার নিয় দেখা দিয়েছে, অনেক সময়য় মনে হয় এই জাতি মেরুদণ্ডর উপর থিতু হয়ে কোনদিন দাঁড়াত পারবেব না। মধ্যযুগীয় ভূত এই জাতিকে এমনভাবে আষ্টে-পৃষ্ঠে বেঁধে রেখেছে তার নাগপাশ কখন কিভাবে ছাড়াতে পারবে একথা এখন একরকম চিন্তা করাও অসম্ভব হয়ে দাঁড়িয়েছেছ।'),
('সিপাহী যুদ্ধের ইতিহাস', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Sipahi_Juddher_Itihas-Ahmed_Sofa-6a44d-216458.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'ইতিহাস: সামরিক ও যুদ্ধ বিগ্রহ', '9789848966464', 'বাংলা', 269, '১ম প্রকাশ ২০১৮, ২য় প্রকাশ, ২০২৩', 450.0, 387, '65% Off', NULL, 5, 'In Stock', 'সিপাই বিদ্রোহ জাতীয় ঘটনার ওপর লেখা ইংরেজি গ্রন্থ অসংখ্য্ কিন্তু বিষয়বস্তুর গুরুত্বের জন্যও আহমদ ছফার এই রচনাটির গুরুত্ব অনস্বীকার্য। ইতিহাস ও সমাজতত্ত্বের ওপর লেখা তাঁর কয়েকটি প্রবন্ধ িইতোমধ্যে প্রকাশিত হয়েছে। তবে ব্যাপক ইতিহাস আলোচনার ভিত্তিতে রচিত গ্রন্থ হিসেবে সিপাহি যুদ্ধের ইতিহাস তাঁর প্রথম রচনা। এ গ্রন্থ প্রকাশ পেয়েছে ঘনার ধারাবাহিকতা চিহ্নিতকরণের প্রয়াস এবং সর্বোপরি লেখকের অনুসন্ধিৎসু মন।'),
('প্রবন্ধসমগ্র - ১ম খণ্ড', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/29a052345_89766.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', NULL, '97898489649190', 'বাংলা', 520, '1st Published, 2014', 600.0, 516, '65% Off', NULL, 5, 'In Stock', '"প্রবন্ধসমগ্র ১ম খণ্ড" বইটির সূচিপত্র: বাঙালি মুসলমানের মন ১৫-১১২ উত্তর ভূমিকা বাঙালি মুসলমানের মন মানিক বন্দ্যোপাধ্যায়ের একটি চরিত্র শিক্ষার দর্শন রবীন্দ্রনাথের সংস্কৃতি-সাধনা বার্ট্রান্ড রাসেল ভবিষ্যতের ভাবনা বাংলার ইতিহাস প্রসঙ্গে একুশে ফেব্রুয়ারি উনিশ শ’ বাহাত্তর বাংলার চিত্র-ঐতিহ্য : সুলতানের সাধনা বাংলাভাষা : রাজনীতির আলােকে ১১৩-১৬০ বাংলাভাষা : রাজনীতির আলােকে বাংলার সাহিত্যাদর্শ ভাষাবিষয়ক চিন্তাভাবনা জীবনানন্দ দাশ : তাঁর কাব্যের লােকজ উপাদান : সাম্প্রতিক নিরিখ সংকটের নানান চেহারা ১৬১-২৩৪ ফারাক্কা ষড়যন্ত্রের নানান মাত্রা মাওলানা ভাসানী : ফারাক্কা গৃহদাহের রাজনীতি মাদ্রাসা শিক্ষার কথা অমৃতভাণ্ড : মাইজভাণ্ডার গ্রামের কথা অনানুষ্ঠানিক শিশুশিক্ষা প্রসঙ্গে তাহলে এই হল গ্রন্থ মেলা একটি খােলা নালিশ সাহিত্যের সুসমাচার স্মৃতির দীয়া কেন আমি বই মেলায় যাব'),
('আহমদ ছফা : কবিতাসমগ্র', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Ahmed_Sofa__Kobitashomogro-Ahmed_Sofa-85075-218997.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'কবিতা সমগ্র', '978-984-8966-58-0', 'বাংলা', 462, '1st Published, 2021', 550.0, 473, '65% Off', NULL, 5, 'In Stock', 'মনীষী-লেখক আমরা তাঁদেরকেই বলি যাঁদের রচনায় একই সঙ্গে যুগ ও যুগান্তরের স্বপ্ন-সাধনা মূর্ত হয়ে ওঠে। প্রয়াত আহমদ ছফা বাংলাদেশের সেরকম মানসিকতাসম্পন্ন একজন লেখক। রচনাশৈলীর সঙ্গে মনীষার এমন সম্মিলন কখনো কখনো ঘটে, তবে সব লেখকের বেলায় ঘটে না। সাহিত্যিক পরিচয়ের ঊর্ধ্বে আমাদের কালের এক চিন্তানায়কের মর্যাদায় তাঁকে অধিষ্ঠিত করেছে তাঁর প্রজ্ঞা, মননশীলতা, অন্তর্দষ্টি, ইতিহাসবোধ, ঐতিহ্য-সচেতনতা, মানবপ্রীতি, সামাজিক দায়বদ্ধতা। তাঁর জীবদ্দশায় যাঁরা হয়তো অনেক বিষয়ে তাঁর সঙ্গে দ্বিমত পোষণ করতেন এমনকি তাঁদের পক্ষেও তাঁর চিন্তার প্রাতিস্বিকতা ও প্রতিভার মৌলিকত্বকে অস্বীকার করার উপায় ছিল না এমন এখনো নেই। প্রবন্ধ সমগ্র গ্রন্থটি আহমদ ছফার পাঠকনন্দিত কিছু প্রবন্ধ নিয়ে গ্রথিত। এগুলো যেমন আলোচিত তেমনই সমালোচিত। বলতে গেলে এটাই প্রবন্ধের স্বার্থকতা। রাজনীতি, অর্থনীতি, সমাজ বিজ্ঞান, রাষ্ট্রাচার, সমালোচনা, জীবন, মূল্যবোধ, ধর্ম, ইতিহাস, দর্শন, নান্দনিকতা, শিক্ষা ব্যবস্থা, গ্রাম, নগর, বুদ্ধিজীবী, সাধারণ মানুষ, চোরাচালান, সাহিত্য-সংস্কৃতি, ভাষা এবং পররাষ্ট্রসহ প্রাত্যাহিক জীবনের আরও অনেক বিষয় প্রকৃষ্ট কৌশলে হৃদয়গ্রাহী ভাষায় মনকাড়া যুক্তিতে বিধৃত। প্রবন্ধকে যদি শরীরের সাথে তুলনা করা হয় তাহলে আত্মজ্ঞান-নিবিড় প্রকৃষ্ট অনুসন্ধানের পক্ষপাতহীন যোজনা আহমদ ছফার প্রবন্ধের অবয়ব, নির্লোভ আভিজাত্যের সাহসী উচ্চারণ মাংশপেশী, দূরদর্শী চেতনার শালীন বাক্যবান তার শক্তি, জাগরনময় অনুভবের প্রীতম প্রতীতি হৃদপিণ্ড, বাস্তবতার নিরিখে অতীত, বর্তমান ও ভবিষ্যতের মুক্তবুদ্ধিঘন সমন্বয় মস্তিষ্ক এবং আকর্ষণীয় বাক্যের মন্দ্রিত প্রাঞ্জলতা তাঁর প্রবন্ধের সৌন্দর্য।'),
('মরণবিলাস', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/Moronbilash-Ahmed_Sofa-2c4d8-432394.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'চিরায়ত উপন্যাস', '9789849848966624', 'বাংলা', 75, '1st Published, 2018', 200.0, 172, '65% Off', NULL, 5, 'In Stock', 'মন্ত্রী হাসপাতালে ভর্তি হওয়ার পরের দিন প্রেসিডেন্ট সাহেব আধ ঘণ্টার মত সময় রোগীর শয্যা পাশে ছিলেন। যেহেতু মন্ত্রী ফজলে ইলাহি সর্বক্ষণ সংজ্ঞাহীন ছিলেন, তাই উভয়ের মধ্যে কোন কথাবার্তা হতে পারেনি। আর অধিক সময় ব্যয় করা প্রেসিডেন্টের পক্ষে সম্ভব হয়নি। তাঁকে তো এক হাতেই জটিল রাষ্ট্রযন্ত্রটি চালাতে হয়। ফজলে ইলাহিকে প্রেসিডেন্টের আগমন সংবাদ জানান হয়েছিল। তখনো তিনি আজকের মত একই রকম বিষণ্ন হয়ে পড়েছিলেন। সবদিক বিবেচনা করে মাওলা বক্স অসুস্থ মন্ত্রিকে দু’চারটা আশার বাক্য শুনিয়ে একটু চাঙ্গা করা যায় কিনা চেষ্টা করল। —স্যার প্রেসিডেন্ট সাহেব আজ আসতে পারেননি। কাল নিশ্চয়ই তিনি আসবেন। কাল যদি তিনি কাজ—কর্মে ব্যস্ত থাকেন, পরশু দিন তো আর মিস করতে পারবেন না। আমাদের প্রেসিডেন্ট সাহেব মন্ত্রিদের মধ্যে আপনাকেই সবচাইতে ভালবাসেন। দেখবেন স্যার, এবার তিনি আপনার সজ্ঞান অবস্থায় খবর নিয়ে সাক্ষাৎ করতে আসবেন। তখন তাঁর সঙ্গে আপনার কথাবার্তা হবে।'),
('নিকট ও দূরের প্রসঙ্গ', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/rokimg_20140203_10852.gif', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'কলাম সমগ্র/সংকলন', NULL, 'বাংলা', NULL, NULL, 200.0, 172, '65% Off', NULL, 5, 'In Stock', NULL),
('পুষ্প বৃক্ষ এবং বিহঙ্গ পুরাণ', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/6c720fa28_183572.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'চিরায়ত উপন্যাস', '9789848965986', 'বাংলা', 108, '1st Published, 2019', 200.0, 172, '65% Off', NULL, 5, 'In Stock', '“পুষ্প বৃক্ষ এবং বিহঙ্গ পুরাণ" বইটির ফ্ল্যাপ এর লেখাঃ পুষ্প বৃক্ষ এবং বিহঙ্গ পুরাণ গ্রন্থটিকে উপন্যাস হিসেবেই গ্রহণ করা হয়েছে। এখানে উপন্যাসের মতাে একটি কাহিনি রয়েছে, যার কেন্দ্রে রয়েছেন। স্বয়ং ঔপন্যাসিক আহমদ ছফা। রাজনৈতিক জীবন বা ব্যক্তি জীবনে আহমদ ছফা সমাজ প্রচলিত সফলতার মুখ কখনাে দেখেছেন তেমনটি আমাদের মনে হয়নি। কিন্তু এই উপন্যাসেই আমরা দেখি, সফলতা ও ব্যর্থতার যে দার্শনিক দিক আহমদ ছফা একান্ত ব্যক্তিগতভাবে বিশ্বাস করতেন এবং লালনপালনও করতেন- তাকেই যেন প্রতীকী উপস্থাপনে তুলে ধরতে চেয়েছেন। তিনি নিজের উপন্যাসগুলাের ভিতর দিয়ে যে অখণ্ড দার্শনিক তত্ত্বকে আনতে চেয়েছেন সেই দর্শনের চূড়ান্ত প্রকাশ যেন পুষ্প বৃক্ষ এবং বিহঙ্গ পুরাণ উপন্যাসে দেখিয়েছেন তাতে তিনি স্পষ্ট করেছেন যে, মানব সমাজের প্রতিনিধি হয়ে, বাংলাদেশের একজন সদস্য হিসেবে বাংলাদেশকেই তাঁর চিন্তা করতে হবে, মানুষ হিসেবেই তাকে নিজের কর্ম পরিকল্পনা নির্ধারণ করতে হবে এবং সতত মাথায় রাখতে হবে বাংলাদেশকে।'),
('গল্পসমগ্র', 'https://rokbucket.rokomari.io/ProductNew20190903/260X372/e8f3516f1_188222.jpg', 'আহমদ ছফা', 'হাওলাদার প্রকাশনী', 'গল্প সমগ্র', '9789848965016', 'বাংলা', 199, '1st Published, 2019', 350.0, 301, '65% Off', NULL, 5, 'Pre-Order', '“গল্পসমগ্র" বইটির ফ্ল্যাপ এর লেখাঃ মনীষী- লেখক আমরা তাদেরকেই বলি যাঁদের রচনায় একই সঙ্গে যুগ ও যুগান্তরের স্বপ্ন-সাধনা মূর্ত হয়ে ওঠে। প্রয়াত আহমদ ছফা আমাদের দেশের সেরকম মানসিকতাসম্পন্ন লেখক ছিলেন। সাহিত্যিক পরিচয়ের উর্ধ্বে আমাদের কালের এক চিন্তানায়কের মর্যাদায় তাঁকে অধিষ্ঠিত করেছে তার প্রজ্ঞা, মননশীলতা, অন্তদৃষ্টি, ইতিহাসবােধ, ঐতিহ্য-সচেতনতা, মানবপ্রীতি, সামাজিক দায়বদ্ধতা। তাঁর জীবদ্দশায় যারা হয়তাে অনেক বিষয়ে তাঁর সঙ্গে দ্বিমত পােষণ করতেন এমনকি তাদের পক্ষেও তাঁর চিন্তার প্রাতিস্বিকতা ও প্রতিভার মৌলিকত্বকে অস্বীকার করার উপায় ছিল না। একথা বলায় যায়, বর্তমান ও আগামীর প্রজন্মকে তাঁর রচনার শরণাপন্ন হতে হবে।'),
